ActiveTutorialLocalData = {}
ActiveTutorialLocalData.tab = {
[1] = {1, 1, "活動引導", "本次活動分為探索關卡，挑戰關卡，試煉關卡；通關指定探索關卡可解鎖對應的挑戰關卡，通過挑戰關卡獲取的試煉道具用於挑戰試煉關卡。", "TutorialPic/Img_Yindao_xh_1", "0"},
[2] = {2, 1, "活動引導", "通關章節內的所有探索關卡後可解鎖對應的試煉關卡，進行試煉可獲得席茲之淚，龍之玉隨後前往心願交換處換取獎勵吧。", "TutorialPic/Img_Yindao_xh_2", "0"},
[3] = {3, 1, "活動引導", "進入探索關卡後點擊地塊操作領航在地圖中移動。", "TutorialPic/Img_Yindao_xh_3", "0"},
[4] = {4, 1, "活動引導", "完成關卡目標後將解鎖後續關卡可以選擇離開或在當前關卡中繼續探索，探索過程中也可以隨時離開關卡。", "TutorialPic/Img_Yindao_xh_4", "0"},
[5] = {5, 1, "活動引導", "普通探索關卡中會隨著領航在地圖中前進可以發現全部的地圖，但在特殊探索關卡中領航只能查看自身周圍的格子。", "TutorialPic/Img_Yindao_xh_6", "0"},
[6] = {6, 1, "活動引導", "在探索過程中會觸發各種事件，在戰鬥時若戰敗不會影響探索進度可以重新進行戰鬥。", "TutorialPic/Img_Yindao_xh_7", "0"},
[7] = {7, 1, "活動引導", "在部分關卡中會存在暫時無法通行的路障，擊敗指定敵人或與指定角色對話將自動解除。", "TutorialPic/Img_Yindao_xh_8", "0"},
[8] = {8, 1, "活動引導", "在特殊探索關卡中存在外觀與普通格相同的陷阱格，請小心的前進吧。", "TutorialPic/Img_Yindao_xh_11", "0"},
[9] = {9, 1, "活動引導", "特殊戰鬥 在作戰開始後會以當前隊伍連續進行兩場戰鬥，在作戰開始前可以通過'敵陣總覽'切換查看敵人資訊，合理的調整隊伍應對兩場戰鬥吧。", "TutorialPic/Img_Yindao_xh_9", "0"},
[10] = {10, 1, "活動引導", "單次試煉若未能擊敗試煉目標則會保留目標剩餘血量，每種難度的試煉目標需通關5次且達成所有勝利條件後可以解鎖對應難度的掃蕩功能。", "TutorialPic/Img_Yindao_xh_10", "0"},
[11] = {11, 2, "劇情活動引導", "劇情活動分為劇情關卡，挑戰關卡，試煉關卡；\n通關挑戰關卡可獲得活動道具「虹色晶塊」。", "TutorialPic/Img_Yindao_ym_1", "0"},
[12] = {12, 2, "劇情活動引導", "使用活動道具「虹色晶塊」在活動商店中與織女星兌換獎勵吧。", "TutorialPic/Img_Yindao_ym_2", "0"},
[13] = {13, 3, "月色深淵引導", "月色深淵為限時活動，挑戰深淵關卡不需要消耗體力，關卡中無法使用好友助戰功能，完成一層的關卡後就會解鎖下一層的關卡，已通過的關卡無法重複挑戰，在月色深淵中由於『蒼霧特性』的影響，在戰鬥中會對敵我雙方產生特殊效果。", "TutorialPic/Img_Yindao_yssy_1", "0"},
[14] = {14, 3, "月色深淵引導", "在月色深淵中每場戰鬥結束後，我方駕駛員的剩餘生命值（百分比）將會被全數繼承，若我方戰敗時則敵方單位的生命值（百分比）也會全數繼承。", "TutorialPic/Img_Yindao_yssy_2", "0"},
[15] = {15, 3, "月色深淵引導", "在戰鬥前可以選擇重置駕駛員狀態，重置後所有駕駛員恢復為滿血狀態，每日可以進行3次重置操作，每日首次重置駕駛員狀態時免費，後續每次重置將需消耗少量能源晶體。（困難模式中只能重置困難模式進度和特性選擇，無法重置駕駛員狀態）", "TutorialPic/Img_Yindao_yssy_3", "0"},
[16] = {16, 3, "月色深淵引導", "月色深淵中分為普通與困難兩種模式，通關所有普通難度的關卡後將解鎖困難模式。", "TutorialPic/Img_Yindao_yssy_4", "0"},
[17] = {17, 3, "月色深淵引導", "開始困難模式前需要設置對應的『蒼霧特性』，玩家可以隨時重置困難關卡的進度，重新選擇『蒼霧特性』進行挑戰。", "TutorialPic/Img_Yindao_yssy_5", "0"},
[18] = {18, 3, "月色深淵引導", "完全通關困難模式後計入排名，將根據玩家通關時的『蒼霧特性』等級，通關時間先後進行排名。", "TutorialPic/Img_Yindao_yssy_6", "0"},
[19] = {19, 4, "外傳活動引導", "外傳活動分為區域探索與試煉關卡，在區域探索中設有劇情與戰鬥關卡；\n參與試煉關卡需要消耗活動道具「星之遺物」。", "TutorialPic/Img_Yindao_wzhd_1", "0"},
[20] = {20, 4, "外傳活動引導", "外傳活動中所有關卡都設有能源儲備需求，若隊伍能源儲備值滿足關卡所需時在戰鬥中可獲得屬性提升效果，反之若不滿足則在戰鬥中將會降低屬性，具體效果可通過儲備詳情處查看；", "TutorialPic/Img_Yindao_wzhd_2", "0"},
[21] = {21, 4, "外傳活動引導", "在區域探索中可獲取活動道具「絕望要素」，收集「絕望要素」可用於提升星變拓展件等級，增加隊伍能源儲備值", "TutorialPic/Img_Yindao_wzhd_3", "0"},
[22] = {22, 4, "外傳活動引導", "參與外傳活動可獲取活動道具「宅急送優惠券」，使用「宅急送優惠券」可在飛速食品宅急送進行訂單派送並獲得獎勵。", "TutorialPic/Img_Yindao_wzhd_4", "0"},
[23] = {23, 4, "外傳活動引導", "本次活動設有7個普通宅急送訂單機與1個無限宅急送訂單，當獲取當前宅急送訂單中所有特殊殘響道具時可選擇切換至下一個宅急送訂單，注：切換後將無法返回上一個宅急送訂單；無限宅急送訂單中不包含特殊殘響道具，需要派送全部訂單物品後可重置無限宅急送訂單；", "TutorialPic/Img_Yindao_wzhd_5", "0"},
[24] = {24, 5, "半周年活動引導", "本次活動分為故事章節與試煉章節，在故事章節中分為劇情關卡與探索關卡；", "TutorialPic/Img_Yindao_xh_12", "0"},
[25] = {25, 5, "半周年活動引導", "通關試煉關卡可獲得活動道具「改變未來的證明」，使用道具「改變未來的證明」在活動商店中與九十九環兌換獎勵吧。", "TutorialPic/Img_Yindao_xh_13", "0"},
[26] = {26, 5, "半周年活動引導", "通過活動商店獲得活動道具「一日通行证證」，使用道具「一日通行证」幫助多洛莉絲完成模擬訓練來獲得獎勵，完成模擬來解鎖回憶劇情吧。", "TutorialPic/Img_Yindao_xh_14", "0"},
[27] = {27, 5, "半周年活動引導", "進入探索關卡後點擊地塊操作領航在地圖中移，通過查看按鈕可以切換為查看地圖模式；", "TutorialPic/Img_Yindao_xh_3", "0"},
[28] = {28, 5, "半周年活動引導", "在探索關卡中完成關卡目標後將解鎖後續關卡可以選擇離開或在當前關卡中繼續探索，探索過程中也可以隨時離開關卡。", "TutorialPic/Img_Yindao_xh_4", "0"},
[29] = {29, 5, "半周年活動引導", "在探索過程中會觸發各種事件，在戰鬥時若戰敗不會影響探索進度可以重新進行戰鬥。", "TutorialPic/Img_Yindao_xh_7", "0"},
[30] = {30, 5, "半周年活動引導", "在部分關卡中會存在暫時無法通行的路障，擊敗指定敵人或與指定角色對話將自動解除。", "TutorialPic/Img_Yindao_xh_8", "0"},
[31] = {31, 5, "半周年活動引導", "在部分關卡中會存在傳送旋渦，進入旋渦將會立刻被傳送至對應的另一個傳送旋渦處。", "TutorialPic/Img_Yindao_xh_15", "0"},
[32] = {32, 5, "半周年活動引導", "特殊戰鬥 在作戰開始後會以當前隊伍連續進行兩場戰鬥，在作戰開始前可以通過'敵陣總覽'切換查看敵人資訊，合理的調整隊伍應對兩場戰鬥吧。", "TutorialPic/Img_Yindao_xh_9", "0"},
[33] = {33, 5, "半周年活動引導", "單次試煉若未能擊敗試煉目標則會保留目標剩餘血量，每種難度的試煉目標達成所有勝利條件後可以解鎖對應難度的掃蕩功能。", "TutorialPic/Img_Yindao_xh_16", "0"},
[34] = {34, 6, "1周年活動引導", "通關試煉關卡可獲得活動道具「聖水滴」，使用道具「聖水滴」在活動商店中與梅莉雅兌換獎勵吧。", "TutorialPic/Img_Yindao_yzn_1", "0"},
[35] = {35, 6, "1周年活動引導", "通過活動商店獲得活動道具「一日特訓券」，使用道具「一日特訓券」幫助珂斯嘉德完成模擬訓練來獲得獎勵。", "TutorialPic/Img_Yindao_yzn_2", "0"},
[36] = {36, 7, "1.5周年活動引導", "本次活動分為故事章節與試煉章節，在故事章節中分為劇情關卡與探索關卡。", "TutorialPic/Img_Yindao_xh_1", "0"},
[37] = {37, 7, "1.5周年活動引導", "通關試煉關卡可獲得活動道具「昔日碎片」，使用道具「昔日碎片」在活動商店中兌換獎勵吧。", "TutorialPic/Img_Yindao_xh_2", "0"},
[38] = {38, 9999, "1.5周年活動引導", "通過活動商店獲得活動道具「全自動調酒代幣」，使用道具「全自動調酒代幣」獲得獎勵，解鎖回憶劇情吧。", "TutorialPic/Img_Yindao_xh_3", "0"},
[39] = {39, 7, "1.5周年活動引導", "單次試煉若未能擊敗試煉目標則會保留目標剩餘血量，每種難度的試煉目標達成所有勝利條件後可以解鎖對應難度的掃蕩功能。", "TutorialPic/Img_Yindao_xh_4", "0"},
[40] = {40, 8, "个人剧情活動引導", "活動期間解鎖並且通關活動劇情第4幕後，可獲得角色裝扮。", "TutorialPic/Img_Yindao_grjq_1", "0"},
[41] = {41, 8, "个人剧情活動引導", "參與活動可獲取活動道具「回音代幣」，使用「回音代幣」可在「憶漣回音」中進行扭蛋並獲得獎勵。", "TutorialPic/Img_Yindao_grjq_2", "0"},
[42] = {42, 8, "个人剧情活動引導", "本次活動設有8個有限扭蛋機與1個無限扭蛋機，當獲取當前扭蛋機中的特殊道具時可選擇切換至下一個扭蛋機。\n註：切換後將無法返回上一個扭蛋機；無限扭蛋機訂單中不包含特殊道具，需要獲取扭蛋機重得物品後可重置無限扭蛋機", "TutorialPic/Img_Yindao_grjq_3", "0"},
[43] = {43, 9, "剧情回顾引导", "劇情回顾分為劇情關卡、挑戰關卡；\n通關挑戰關卡可獲得「商店货币」。", "TutorialPic/Img_Yindao_jqhg_1", "0"},
[44] = {44, 9, "剧情回顾引导", "使用对应的「商店货币」可在商店中兌換獎勵。", "TutorialPic/Img_Yindao_jqhg_2", "0"},
[45] = {45, 10, "2周年活動引導", "本次活動分為故事章節與試煉章節，在故事章節中分為劇情關卡與探索關卡。", "TutorialPic/Img_Yindao_2zn_1", "0"},
[46] = {46, 10, "2周年活動引導", "通關試煉關卡可獲得活動道具「獨角」，使用道具「獨角」在活動商店中兌換獎勵吧。", "TutorialPic/Img_Yindao_2zn_2", "0"},
[47] = {47, 9999, "2周年活動引導", "單次試煉若未能擊敗試煉目標則會保留目標剩餘血量，每種難度的試煉目標達成所有勝利條件後可以解鎖對應難度的掃蕩功能。", "TutorialPic/Img_Yindao_2zn_3", "0"},
[48] = {48, 996, "宇宙武道会引导", "上榜規則：根據玩家“最大連勝場數”進行排行排名。", "TutorialPic/Img_Yindao_wudaohui_1", "0"},
[49] = {49, 996, "宇宙武道会引导", "進攻陣型和防守陣型中不能配置同一角色。", "TutorialPic/Img_Yindao_wudaohui_2", "0"},
[50] = {50, 996, "宇宙武道会引导", "對戰順序：第一輪，己方進攻陣型對戰對手防守陣型；第二輪，對手進攻陣型對戰己方防守陣型", "TutorialPic/Img_Yindao_wudaohui_3", "0"},
[51] = {51, 997, "肥皂泡泡", "沿著規定好的路線，為駕駛員打上肥皂吧！", "TutorialPic/Img_CuozaoBangzhu1", "0"},
[52] = {52, 997, "肥皂泡泡", "正確的路線，能最大效率的利用肥皂~完成時間越短，評分越高", "TutorialPic/Img_CuozaoBangzhu2", "0"},
[53] = {53, 998, "捕捉水生動物", "因在海洋作戰，偶爾會有棲息於此的生物掛在駕駛員身上", "TutorialPic/Img_CuozaoBangzhu3", "0"},
[54] = {54, 998, "捕捉水生動物", "看準時機點擊螢幕按鈕，幫助駕駛員趕走身上的動物吧！", "TutorialPic/Img_CuozaoBangzhu4", "0"},
[55] = {55, 999, "抉擇！護膚品之謎", "為駕駛員挑選最合適的護膚品吧，不同地區的駕駛員適用的護膚品也不同\n可不要選錯護膚品哦，不同的護膚品，保養功效也不同~", "TutorialPic/Img_CuozaoBangzhu5", "0"},
[56] = {56, 999, "抉擇！護膚品之謎", "仔細看好每個問題，才能選出最適合駕駛員的那一款~答對的題目越多，選擇的護膚品就越合適", "TutorialPic/Img_CuozaoBangzhu6", "0"},
[57] = {57, 1000, "按摩點擊", "把握時機，點擊出現的領航頭像吧！", "TutorialPic/Img_Yindao_BathGame1", "0"},
[58] = {58, 1000, "按摩點擊", "點擊成功的次數越多，越能幫助駕駛員放松身心，獲得的評分也會越高。", "TutorialPic/Img_Yindao_BathGame1", "0"},
[59] = {59, 1001, "清潔身體", "仔細觀察駕駛員身上的痕跡，並選擇正確的道具，為駕駛員清潔身體。\n拖動道具，滑動經過身上的痕跡，即可完成清潔。", "TutorialPic/Img_Yindao_BathGame3", "0"},
[60] = {60, 1001, "清潔身體", "最後，為駕駛員抹上口紅，完成通感維護。\n拖動口紅，滑動經過駕駛員的嘴唇，即可完成通感維護。", "TutorialPic/Img_Yindao_BathGame3", "0"},
[61] = {61, 1002, "節奏按摩", "跟隨手掌與捶打的節奏，為駕駛員按摩。\n在正確的時機點擊手指的位置，即可為駕駛員進行節奏按摩。", "TutorialPic/Img_Yindao_BathGame2", "0"},
[62] = {62, 1002, "節奏按摩", "連續成功的按摩次數越多，分數越高。", "TutorialPic/Img_Yindao_BathGame2", "0"},
[63] = {63, 1003, "通感維護", "「通感維護」是與駕駛員進行更深入交流的地方。", "TutorialPic/Img_Yindao_cz_1", "0"},
[64] = {64, 1003, "通感維護", "滿足駕駛員的好感條件，並使用指定的消耗道具後，即可與駕駛員進行「通感維護」。", "TutorialPic/Img_Yindao_cz_2", "0"},
}
return ActiveTutorialLocalData
